import{_ as e,o as a,c as l,a4 as r}from"./chunks/framework.2-Vke5-n.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"コードレビュー<br>ガイドライン","tagline":"Code Review Guidelines","actions":[{"theme":"brand","text":"コードレビューガイドライン","link":"./code_review.md"}]}},"headers":[],"relativePath":"documents/forCodeReview/index.md","filePath":"documents/forCodeReview/index.md"}'),i={name:"documents/forCodeReview/index.md"};function o(n,t,s,d,c,h){return a(),l("div",null,[...t[0]||(t[0]=[r('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p><a href="https://xn--97-273ae6a4irb6e2hsoiozc2g4b8082p.com/" target="_blank" rel="noreferrer">プログラマが知るべき97のこと</a> の14個目に「コードレビュー」について記述がある。コードレビューの目的は「コードの質を上げ、欠陥を減らすため」だけではなく、「チーム全員に同じ知識を共有させること、またコーディングにおいて全員が守るべきガイドラインを確立すること」が大切だとある。そして「 レビューを楽しいものにすること」がおそらく最も有効だとある。</p><p>コードレビューを楽しい場にするためにも、レビュアー／レビュイー が同じ方向性を向くことが重要である。同時に、人によってコメントなどの表現が揺れ、それにより認識齟齬があると楽しむ以前の問題であるため、守るべきルールも存在するはずである。このガイドラインは推奨する行動と、守るべきルールの両方を定義し、コードレビューをより有意義で学びが多く、生産性と品質を高める場とすることを目指す。</p><div class="info custom-block"><p class="custom-block-title">参考</p><p><a href="https://about.gitlab.com/ja-jp/topics/version-control/what-is-code-review/" target="_blank" rel="noreferrer">コードレビューとは | GitLab</a> にも似た旨の記載がある</p></div><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署／プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="適用範囲" tabindex="-1">適用範囲 <a class="header-anchor" href="#適用範囲" aria-label="Permalink to &quot;適用範囲&quot;">​</a></h2><p>GitHubやGitLabなどのサービスを利用した、コーディングについてのレビューのみを対象とする。</p><p>プロジェクト計画によっては、開発プロセスを複数の「フェーズ」に分割し、各フェーズの終了時点で「フェーズレビュー」を挟むようなケースも考えられるが、それらは対象外とする。</p><h2 id="定義" tabindex="-1">定義 <a class="header-anchor" href="#定義" aria-label="Permalink to &quot;定義&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">用語</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;">レビュアー</td><td style="text-align:left;">レビューを行う側の担当者</td></tr><tr><td style="text-align:left;">レビュイー</td><td style="text-align:left;">レビューを依頼する側の担当者。プルリクエストを起票する開発者でもある</td></tr><tr><td style="text-align:left;">プルリクエスト</td><td style="text-align:left;">GitLabではマージリクエストともいうが、本ガイドラインではプルリクエストに統一して呼称する</td></tr></tbody></table><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、村田靖拓、山本竜玄、清水雄一郎、水田祐介</li><li><strong>レビュアー</strong>: 谷村元気、栗田真、後藤玲雄、八木雅斗、辻大志郎</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2025.05.02 <a href="https://future-architect.github.io/articles/20250502a/" target="_blank" rel="noreferrer">コードレビューガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./code_review.html">コードレビューガイドライン</a></p></div>',16)])])}const b=e(i,[["render",o]]);export{u as __pageData,b as default};
